import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const {
    imageUrl,
    scenePosition = [0, 0, 0],
    cinematicPrimitives = [],
  } = config;

  // === ROOT GROUP ===
  const group = new THREE.Group();
  group.position.fromArray(scenePosition);
  group.userData.handlers = {};
  group.userData.primitiveCleanups = [];

  // === PLANE GEOMETRY ===
  const geometry = new THREE.PlaneGeometry(2.5, 1.5, 1, 1);

  // === MATERIAL WITH SHADER NODES ===
  const colorUniform = uniform(new THREE.Color(0xffffff));
  const hoverAlpha = uniform(1.0);
  const materialNode = new MeshBasicNodeMaterial({
    colorSpace: THREE.SRGBColorSpace,
  });

  // Load texture asynchronously
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      materialNode.map = texture;
      materialNode.needsUpdate = true;
    });
  }

  // Basic hover effect on alpha via shader nodes
  materialNode.transparent = true;
  materialNode.opacityNode = hoverAlpha;

  // === MESH ===
  const mesh = new THREE.Mesh(geometry, materialNode);
  group.add(mesh);

  // === INTERACTION STATE ===
  let isHovering = false;
  let hoverTimeline = null;
  let pressTimeline = null;

  // === HOVER HANDLERS ===
  group.userData.handlers.onHover = () => {
    if (isHovering) return;
    isHovering = true;

    // Kill prior hover timeline if active
    if (hoverTimeline) hoverTimeline.kill();

    // Rise-in: y +0.15, power3.out, 0.7s
    hoverTimeline = gsap.to(mesh.position, {
      y: 0.15,
      duration: 0.7,
      ease: 'power3.out',
      overwrite: 'auto',
    });
  };

  group.userData.handlers.onHoverEnd = () => {
    if (!isHovering) return;
    isHovering = false;

    // Return to y=0 with settle motion
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(mesh.position, {
      y: 0,
      duration: 0.9,
      ease: 'power4.out',
      overwrite: 'auto',
    });
  };

  // === CLICK HANDLER ===
  group.userData.handlers.onClick = () => {
    // Press-down: scale 0.97, 120ms, back.out
    if (pressTimeline) pressTimeline.kill();
    pressTimeline = gsap.to(mesh.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out',
      yoyo: true,
      repeat: 1,
      overwrite: 'auto',
    });

    // Emit navigation event
    ctx.emit('hub-pricing.select', { quote: true });
  };

  // === APPLY CINEMATIC PRIMITIVES ===
  for (const primitive of cinematicPrimitives) {
    if (primitive.name === 'parallax-scroll' && primitive.trigger === 'scroll') {
      const result = ctx.primitives['parallax-scroll'](group, primitive.params || {});
      if (result && result.cleanup) {
        group.userData.primitiveCleanups.push(result.cleanup);
      }
    }
  }

  // === CLEANUP ===
  group.userData.cleanup = () => {
    geometry.dispose();
    materialNode.dispose();
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();
    for (const cleanup of group.userData.primitiveCleanups) {
      cleanup();
    }
  };

  return group;
}
